 h,e,r=g['h'],g['e'],g['r'];x=h['contentX'];w=h['contentW'];top=h['hy']+h['hit']+8;dock=[h['dockX']+h['dockW']/2,h['dockY']+h['hit']/2];more=[r['hx']+r['hw']-r['hit']/2,r['hy']+r['hit']/2]
